(function(root){
const core=typeof module!=='undefined'?require('./game-core.js'):root.CourierCore;
const manifest={id:12,destination:{name:'North Outpost',address:{gate:'east'}},items:[{name:'water',quantity:3},{name:'medicine',quantity:2}],notes:null,'delivery-zone':'north'};
const chapters=[
{id:'requests',number:1,title:'Requests and responses',story:'The outpost’s supply line is quiet. Dispatcher Mara asks Pip to contact the depot before anyone sends a parcel.',outcome:'Identify clients and servers, explain an API contract, and recognize request/response parts and HTTPS.'},
{id:'json',number:2,title:'JSON basics',story:'The depot answered. Now Mara needs a manifest the depot’s software can read. Pip checks each label before dispatch.',outcome:'Write valid JSON using strings, numbers, booleans, null, arrays, and objects.'},
{id:'reading',number:3,title:'Reading structured data',story:'A shipment has several destinations and supplies. Help Pip read exactly the information needed to route it.',outcome:'Read fields, nested objects, array entries, and distinguish missing values from null.'},
{id:'practice',number:null,title:'Original practice',story:'Replay the original three prototype deliveries whenever you want.',outcome:'Try GET, POST, and reading one response field. POST receives a fuller explanation in the planned Chapter 9.'}
];
function choice(id,title,description,task,options,answer,explanation,example){return {id,chapter:'requests',kind:'choice',title,description,task,options,answer,success:explanation,example,hints:['Think about who sends the request and what the message contains.',explanation],solution:options[answer],concept:'REQUESTS AND RESPONSES'}}
function json(id,title,description,task,starter,expected,success,example){return {id,chapter:'json',kind:'json',title,description,task,starter,expected,success,example,solution:JSON.stringify(expected,null,2),hints:['JSON uses double-quoted keys and strings. Numbers, true, false, and null are unquoted.',task],concept:'JSON BASICS'}}
function read(id,title,description,task,starter,expected,success,example){return {id,chapter:'reading',kind:'javascript',title,description,task,starter,expected,success,example,data:manifest,solution:'report('+({field:'data.id',nested:'data.destination.name',index:'data.items[0].name',combine:'data.items[1].quantity',bracket:'data["delivery-zone"]',missing:'[data.notes === null, data.trackingCode === undefined]'}[id])+');',hints:['Follow the fields in the manifest from the outside inward. Array positions start at 0.',task],concept:'READING STRUCTURED DATA'}}
const lessons=[
choice('client','Who sends the request?','Mara asks the outpost’s browser to check the depot inventory. A client initiates a request; the server processes it and returns a response.','Select the client in this exchange.',['The outpost’s browser','The depot’s API server','The inventory JSON'],0,'The browser is the client. Pip represents the journey of the request; the depot is the server. The returned JSON is data, not a server.','Client sends a request.\nServer returns a response.'),
choice('contract','Follow the depot’s rules.','An API defines how software interacts: available operations, expected inputs, and outputs. This game uses a web API over HTTP; APIs can also exist without HTTP.','Which rule describes this depot’s API contract?',['Any address must return any requested data.','GET /api/supplies returns supply information.','JSON decides which network route is available.'],1,'An API contract describes supported operations and their inputs and outputs. Here, GET /api/supplies requests information.','Operation: GET /api/supplies\nSuccess: 200 with supply data'),
{id:'address',chapter:'requests',kind:'request',concept:'REQUEST URL',title:'Contact the supply desk.',description:'A request names an operation and an address. GET asks for information. The JavaScript is provided; only change the address. No physical stock moves when you read inventory.',task:'Replace /api/unknown with /api/supplies, then run the request.',starter:'const response = await fetch("/api/unknown");\nconst data = await response.json();\nreport(data);',solution:core.missions[0].solution,route:'/api/supplies',expected:{item:'water',quantity:3,available:true},success:'200 OK. The depot returned inventory data. You changed the request address; the JSON describes supplies rather than physically delivering them.',example:'fetch("/api/supplies")\n// Sends GET to the supply endpoint.',hints:['The address must match a route the depot supports.','Use fetch("/api/supplies"). Keep the next two lines.']},
choice('parts','Separate request and response.','The request has a method, URL, headers, and sometimes a body. The response has a status, headers, and sometimes a body. Here the depot returned 200 OK.','Which part tells you the result category?',['The request URL','The response status','The JSON property name'],1,'200 is a response status code indicating success. JSON is the body’s format; headers carry metadata. A response can also have no body.','Request: GET /api/supplies\nResponse status: 200 OK\nResponse body: {"item":"water"}'),
choice('metadata','Read the message label.','Headers describe a message. Content-Type: application/json says its body is JSON. A body can also contain HTML, images, or other formats.','What does this response header describe?',['The response body’s format','The number of supplies','The client’s identity'],0,'Content-Type identifies the body’s media type. application/json labels JSON data; it does not guarantee that all required fields are correct.','Response header:\nContent-Type: application/json'),
choice('https','Protect the route.', 'Mara wants the real depot connection protected in transit. HTTPS uses TLS to encrypt the connection and authenticate the server. This game stays simulated and makes no real API calls.','Which address uses HTTPS?',['http://depot.example/api/supplies','https://depot.example/api/supplies','/api/supplies'],1,'https:// selects HTTP over TLS. A relative URL inherits the page’s origin and scheme. HTTPS protects transport; it does not replace permissions or data validation.','https://depot.example/api/supplies\nScheme: https'),
json('strings','Write a readable label.','The depot accepts JSON text. Object keys and strings use double quotes. JSON can represent an object, array, or a single value.','Fix this object so item is the string "water".','{ item: \'water\' }',{item:'water'},'The label is valid JSON. Both the key and string value use double quotes. JSON is text; a JavaScript object is a value in running code.','{"item":"water"}\n\nA standalone JSON string is also valid:\n"water"'),
json('numbers','Count the supplies.','A number is different from a string containing digits. JSON numbers can include decimals or exponents, but not NaN or Infinity.','Make quantity the number 3, not the string "3".','{ "quantity": "3" }',{quantity:3},'quantity is a number. "3" would be text, which may fail the depot’s quantity rules.','{"quantity":3,"weight":1.5}'),
json('values','Mark what is known.','true and false are boolean values. null explicitly represents no value. All three are lowercase and unquoted.','Use the boolean true for ready, false for damaged, and null for notes.','{ "ready": "true", "damaged": "false", "notes": "null" }',{ready:true,damaged:false,notes:null},'The booleans and null have the correct types. null is different from the string "null", and false is different from "false".','{"ready":true,"damaged":false,"notes":null}'),
json('arrays','Pack a list.', 'An array is an ordered list in square brackets. Each entry is a JSON value. An object groups named properties in braces.','Make items an array containing "water", then "medicine".','{ "items": "water, medicine" }',{items:['water','medicine']},'items is an array containing two separate strings. Its order is preserved; a comma inside one string would not create two entries.','{"items":["water","medicine"]}'),
json('syntax','Repair the manifest.', 'JSON permits whitespace, but not comments, single-quoted strings, or trailing commas. Fixing syntax makes text readable; an API may still require specific fields and types.','Remove the trailing commas. Keep item as "water" and quantity as 3.','{\n  "item": "water",\n  "quantity": 3,\n}',{item:'water',quantity:3},'The manifest parses as JSON. A comma separates entries; there is no comma after the final property. Next, check field names and value types.','{"item":"water","quantity":3}'),
json('manifest','Prepare the complete label.', 'Mara needs a complete manifest. Combine named properties, an ordered list, and the value types you practiced. This check happens locally at the outpost.','Create an object with item "water", quantity 3, ready true, notes null, and tags ["urgent", "fragile"].','{\n  "item": "water"\n}',{item:'water',quantity:3,ready:true,notes:null,tags:['urgent','fragile']},'The manifest is valid and has the expected values and types. You combined strings, a number, a boolean, null, an array, and an object.', 'Example with different values:\n{"item":"food","quantity":2,"ready":false,"notes":null,"tags":["dry"]}'),
read('field','Find the shipment ID.','The parsed manifest below is provided as the JavaScript variable data. report() is a game helper that displays your answer. Dot notation reads a named property.','Report data.id instead of the whole manifest.','report(data);',12,'Shipment 12 selected. data.id reads the id property. JSON is text; here data already contains the parsed JavaScript value.','report(data.id);'),
read('nested','Find the destination.','destination is an object inside data. Read its name by following each property in order.','Report the name inside destination.','report(data.destination);','North Outpost','Destination: North Outpost. data.destination.name follows two object properties.','Different nested field:\nreport(data.destination.address);'),
read('index','Inspect the first item.','items is an array. JavaScript indexes start at 0, so data.items[0] reads its first object.','Report the name of the first item.','report(data.items);','water','The first item is water. [0] selects its object; .name reads that object’s name.','First object:\nreport(data.items[0]);'),
read('combine','Count the medicine.', 'Combine an array index with a property lookup. Medicine is the second entry in items, at index 1.','Report the second item’s quantity.','report(data.items[0].quantity);',2,'Medicine quantity: 2. data.items[1].quantity selects the second item, then its quantity.','First item’s quantity:\nreport(data.items[0].quantity);'),
read('bracket','Read a special field name.', 'Bracket notation accepts a quoted property name. Use it when a name contains a hyphen, or when the key comes from a variable.','Report the value of "delivery-zone".','report(data["id"]);','north','The delivery zone is north. data["delivery-zone"] reads one named property; dot notation with a hyphen would be interpreted as subtraction.','Both forms read the ID:\nreport(data.id);\nreport(data["id"]);'),
read('missing','Distinguish unknown from absent.', 'notes exists with value null. trackingCode is absent, so reading it in JavaScript produces undefined. undefined is not a JSON value. === compares values without converting types.','Report an array of two checks: notes is null; trackingCode is undefined. Both should be true.','report([\n  data.notes === "null",\n  data.trackingCode === null\n]);',[true,true],'Both checks are true. An explicit null and an absent property are different. You can now read this shipment without confusing missing data with a value supplied as null.','Example comparison:\nreport(data.id === 12);')
];
const requestHints={client:'Identify the software that starts the exchange.',contract:'A contract names a supported operation and its expected result.',parts:'Look for a numbered code in the response metadata.',metadata:'Content-Type describes the format of a message body.',https:'Look at the scheme before ://. TLS protection uses https.'};
lessons.filter(m=>m.kind==='choice').forEach(m=>m.hints[0]=requestHints[m.id]);
core.missions.forEach((m,i)=>lessons.push({...m,id:'legacy-'+i,chapter:'practice',kind:'legacy',legacyIndex:i,hints:[m.hint],example:m.solution}));
function equal(a,b){if(a===b)return true;if(a===null||b===null||typeof a!=='object'||typeof b!=='object')return false;if(Array.isArray(a)!==Array.isArray(b))return false;const ak=Object.keys(a),bk=Object.keys(b);return ak.length===bk.length&&bk.every(k=>Object.prototype.hasOwnProperty.call(a,k)&&equal(a[k],b[k]))}
function assess(m,result){
 if(result.error)return {ok:false,message:result.error};
 if(m.kind==='choice'){const ok=result.selected===m.answer;return {ok,message:ok?m.success:'Not quite. '+m.hints[0]+' Review the explanation and try another answer.'}}
 if(m.kind==='legacy')return core.validate(m.legacyIndex,result.calls,result.reports);
 const value=m.kind==='json'?result.value:result.reports.at(-1);
 if(m.kind==='request'&&!result.calls.some(c=>c.url===m.route&&c.ok))return {ok:false,message:result.calls.at(-1)?.body?.error||'Send the request to the supply endpoint in your task.'};
 const ok=equal(value,m.expected);return {ok,message:ok?m.success:m.kind==='json'?'The JSON syntax is valid. Check the required fields, exact value types, and array order.':m.id==='missing'?'Compare null without quotes, and use undefined for the absent property. Report the two boolean checks in an array.':'Check the task and the manifest. Report only the requested value, using the correct field or array index.'};
}
const api={chapters,lessons,equal,assess};root.CourierCurriculum=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
